Here is a quick reference guide for basic program structure, function definitions, and input/output syntax in Python and C++:

### Python Reference

```python
# Function declaration
def calculate_total(price, quantity):
    total = price * quantity
    return total

# Standard input and output
user_input = input("Enter a value: ")
print("You entered:", user_input)

# Conditional statements
if total > 100:
    print("Discount applied")
elif total > 50:
    print("Small discount")
else:
    print("No discount")

# Loops
for i in range(5):
    print(i)
```

---

### C++ Reference

```cpp
#include <iostream>

// Function declaration
int calculateTotal(int price, int quantity) {
    int total = price * quantity;
    return total;
}

int main() {
    // Standard input and output
    int value;
    std::cout << "Enter a value: ";
    std::cin >> value;

    // Conditional statements
    if (value > 100) {
        std::cout << "High value" << std::endl;
    } else {
        std::cout << "Low value" << std::endl;
    }

    // Loops
    for (int i = 0; i < 5; i++) {
        std::cout << i << std::endl;
    }

    return 0;
}
```

